const EventEmitter = require('events');

class CircuitBreaker extends EventEmitter {
  constructor(options = {}) {
    super();
    this.failureThreshold = options.failureThreshold || 5;
    this.resetTimeout = options.resetTimeout || 30000;
    this.failures = 0;
    this.state = 'CLOSED';
    this.lastFailureTime = null;
  }

  async execute(fn) {
    if (this.state === 'OPEN') {
      if (Date.now() - this.lastFailureTime >= this.resetTimeout) {
        this.state = 'HALF_OPEN';
      } else {
        throw new Error('Circuit breaker is OPEN');
      }
    }
    try {
      const result = await fn();
      this.onSuccess();
      return result;
    } catch (err) {
      this.onFailure();
      throw err;
    }
  }

  onSuccess() {
    this.failures = 0;
    this.state = 'CLOSED';
  }

  onFailure() {
    this.failures++;
    this.lastFailureTime = Date.now();
    if (this.failures >= this.failureThreshold) {
      this.state = 'OPEN';
      this.emit('open');
    }
  }
}

class SearchIndex {
  constructor(maxDocSize = 1024) {
    this.documents = new Map();
    this.invertedIndex = new Map();
    this.maxDocSize = maxDocSize;
    this.indexBuffer = Buffer.allocUnsafe(4096);
    this.bufferOffset = 0;
  }

  tokenize(text) {
    return text.toLowerCase().replace(/[^a-z0-9\s]/g, '').split(/\s+/).filter(t => t.length > 0);
  }

  computeTokenWeight(token, docId) {
    const tf = this._termFrequency(token, docId);
    const idf = Math.log(this.documents.size / (1 + this._documentFrequency(token)));
    return tf * idf;
  }

  _termFrequency(token, docId) {
    const doc = this.documents.get(docId);
    if (!doc) return 0;
    const tokens = this.tokenize(doc.content);
    return tokens.filter(t => t === token).length / tokens.length;
  }

  _documentFrequency(token) {
    return this.invertedIndex.has(token) ? this.invertedIndex.get(token).size : 0;
  }

  _writeToBuffer(docId, tokenData) {
    const header = Buffer.from(docId.toString().padStart(8, '0'));
    const payload = Buffer.from(JSON.stringify(tokenData));
    const totalLen = header.length + payload.length + 4;

    // Write length prefix (4 bytes) + header + payload
    const requiredSpace = this.bufferOffset + totalLen;
    if (requiredSpace > this.indexBuffer.length) {
      // Resize strategy: double or fit, whichever is larger
      const newSize = Math.max(this.indexBuffer.length * 2, requiredSpace);
      const newBuffer = Buffer.allocUnsafe(newSize);
      this.indexBuffer.copy(newBuffer, 0, 0, this.bufferOffset);
      this.indexBuffer = newBuffer;
    }

    this.indexBuffer.writeUInt32LE(totalLen, this.bufferOffset);
    header.copy(this.indexBuffer, this.bufferOffset + 4);
    payload.copy(this.indexBuffer, this.bufferOffset + 4 + header.length);
    this.bufferOffset += totalLen;
  }

  addDocument(docId, content) {
    if (typeof content !== 'string') {
      throw new TypeError('Content must be a string');
    }

    // Size validation uses byte length of the raw content
    const contentByteLen = Buffer.byteLength(content, 'utf8');
    if (contentByteLen > this.maxDocSize) {
      throw new RangeError(`Document exceeds max size of ${this.maxDocSize} bytes`);
    }

    this.documents.set(docId, { content, indexedAt: Date.now() });
    const tokens = this.tokenize(content);
    const tokenWeights = {};

    for (const token of tokens) {
      if (!this.invertedIndex.has(token)) {
        this.invertedIndex.set(token, new Set());
      }
      this.invertedIndex.get(token).add(docId);
      tokenWeights[token] = this.computeTokenWeight(token, docId);
    }

    this._writeToBuffer(docId, tokenWeights);
    return { docId, tokenCount: tokens.length };
  }

  search(query, limit = 10) {
    const queryTokens = this.tokenize(query);
    const scores = new Map();

    for (const token of queryTokens) {
      const docs = this.invertedIndex.get(token);
      if (!docs) continue;
      for (const docId of docs) {
        const weight = this.computeTokenWeight(token, docId);
        scores.set(docId, (scores.get(docId) || 0) + weight);
      }
    }

    return Array.from(scores.entries())
      .sort((a, b) => b[1] - a[1])
      .slice(0, limit)
      .map(([docId, score]) => ({ docId, score }));
  }

  readBufferEntry(offset) {
    if (offset >= this.bufferOffset) return null;
    const len = this.indexBuffer.readUInt32LE(offset);
    return this.indexBuffer.slice(offset + 4, offset + len);
  }
}

class SearchService {
  constructor() {
    this.index = new SearchIndex(65536);
    this.breaker = new CircuitBreaker({ failureThreshold: 3, resetTimeout: 10000 });
    this.batchQueue = [];
    this.batchSize = 50;
  }

  async indexDocument(docId, content) {
    return this.breaker.execute(async () => {
      return this.index.addDocument(docId, content);
    });
  }

  async batchIndex(documents) {
    const results = [];
    for (const doc of documents) {
      try {
        const result = await this.indexDocument(doc.id, doc.content);
        results.push({ success: true, ...result });
      } catch (err) {
        results.push({ success: false, docId: doc.id, error: err.message });
      }
    }
    return results;
  }

  async search(query) {
    return this.breaker.execute(async () => {
      return this.index.search(query);
    });
  }

  getBufferStats() {
    return {
      allocated: this.index.indexBuffer.length,
      used: this.index.bufferOffset,
      utilization: (this.index.bufferOffset / this.index.indexBuffer.length * 100).toFixed(2) + '%'
    };
  }
}

module.exports = { SearchService, SearchIndex, CircuitBreaker };
